import React from 'react'
import { connect } from 'react-redux'
import { Row, Col, Icon, Button, Tag } from 'antd'
import swal from 'sweetalert2'
import QueryString from 'query-string'
import PropTypes from 'prop-types'
import moment from 'moment-timezone'
import LayoutContent from '../../../components/utility/layoutContent'
import LayoutContentWrapper from '../../../components/utility/layoutWrapper'
import PermissionChecker from '../../../components/permissionChecker'
import FailedFetchAlert from '../../../components/failedFetchDataAlert'
import {
  FilterInput,
  FilterDateRange
} from '../../../components/tables/helperCells'
import QuerySearchBuilder from '../../../helpers/querySearchBuilder'
import TableWrapper from './followupList.style'
import claimActions from '../../redux/claims/actions'
import loadingActions from '../../../redux/loading/actions'
import errorActions from '../../../redux/error/actions'
import teamAction from '../../redux/team/actions'
import policyActions from '../../../redux/policy/actions'
import { ColumnSearchProps } from '../../../components/SearchFilters'

const {
  getOpenClaims,
  getClaimFilters,
  resetReduxStateClaim,
  sendClaimsReport,
  resetValidateStatus
} = claimActions
const { getProducts } = policyActions
const { resetLoadingRedux } = loadingActions
const { resetErrorRedux } = errorActions
const { getListGroups } = teamAction

class OpenClaims extends React.Component {
  constructor (props) {
    super(props)
    this.state = {
      data: [],
      loading: false,
      failedMessage: '',
      userEmail: '',
      permissions: [],
      searchTextQuery: {},
      isChange: false,
      filteredInfo: {},
      claimsFilter: {},
      groups: [],
      displaySafeScreen: false,
      validatePopupMessage: '',
      displayLimitAlert: false,
      payload: {},
      gojekProduct: undefined
    }
  }

  fetch = (params = {}) => {
    const { page, page_size: pageCount } = params
    const pageNumber = Number(page) || 1
    const pageSize = Number(pageCount) || 50
    delete params.page
    delete params.page_size
    this.setState({
      page_size: pageSize,
      page: pageNumber,
      claimsFilter: params
    })
    this.props.getOpenClaims({ query: { page: pageNumber, page_size: pageSize, ...params } })
  };

  componentWillReceiveProps (nextProps) {
    const { profileData } = nextProps
    const { email } = profileData
    const { listGroups } = nextProps.groupLists
    if (listGroups !== undefined) {
      this.setState({ groups: listGroups })
    }
    if (email !== undefined) {
      this.setState({
        userEmail: email
      })
    }
  }

  componentDidMount () {
    const querySearch = QueryString.parse(this.props.location.search)
    this.fetch(querySearch)
    this.props.getClaimFilters()
    this.props.getListGroups()
    this.props.getProducts()
  }

  componentWillUnmount () {
    this.props.resetReduxStateClaim()
  }

  resetReduxState = () => {
    this.props.resetReduxStateClaim()
  };

  detailPage = id => {
    const { history } = this.props
    history.push(`/claims/${id}`)
  };

  onInputChange = (event, identifier) => {
    this.setState({
      searchTextQuery: { [identifier]: event.target.value },
      isChange: true
    })
  };

  onSearch = (e, identifier, filterType) => {
    let dateSearch = {}
    if (filterType === 'date_range') {
      dateSearch = {
        [`${identifier}`]: [e.startDate, e.endDate]
      }
      this.setState({
        [identifier]: false, // set as not visible
        searchTextQuery: dateSearch,
        isChange: true
      })
    } else {
      e.preventDefault()
    }
    const { searchTextQuery } = this.state
    const { history, location } = this.props
    const finalFilter = { ...searchTextQuery, ...dateSearch }
    const searchQuery = QuerySearchBuilder(finalFilter)
    history.push({
      pathname: location.pathname,
      search: searchQuery
    })
    if (
      Object.values(searchTextQuery).length ||
      Object.values(dateSearch).length
    ) {
      this.setState({
        policy_number: false,
        claim_no: false,
        application_no: false,
        searchTextQuery: finalFilter
      })
      this.fetch(finalFilter)
    }
  };

  resetFilter = () => {
    const { history, location } = this.props
    location.search = ''
    history.push(location.pathname)
    this.setState({
      searchText: '',
      loading: true,
      searchTextQuery: {},
      claimsFilter: {},
      filteredInfo: {},
      clearDate: true
    })
    this.props.resetReduxStateClaim()
    this.fetch()
  };

  handleSearch = (value, key) => {
    const { searchTextQuery } = this.state
    this.fetch({
      ...searchTextQuery,
      [key]: value
    })
  }

  handleTableChange = (pagination, filters) => {
    const { searchTextQuery, filteredInfo } = this.state
    const { history, location } = this.props
    const { pageSize, current } = pagination
    const filterObj = {}

    Object.keys(filters).map((key) => {
      let value = filters[key] || []
      value = Array.isArray(value) ? value[0] : value
      if (value) filterObj[key] = value
      return value
    })

    const finalFilter = {
      ...searchTextQuery,
      ...filterObj,
      page: current,
      page_size: pageSize
    }

    const searchQuery = QuerySearchBuilder(finalFilter)
    history.push({
      pathname: location.pathname,
      search: searchQuery
    })

    this.setState({
      policy_number: false,
      claim_no: false,
      application_no: false,
      onSearchQuery: finalFilter,
      searchTextQuery: finalFilter,
      filteredInfo: { ...filterObj },
      page: current,
      page_size: pageSize
    })

    this.props.getOpenClaims({ query: { page: current, page_size: pageSize, ...finalFilter } })
    if (JSON.stringify(filterObj) === JSON.stringify(filteredInfo)) return
    this.fetch(finalFilter)
  };

  downloadExcel = () => {
    const { userDetail } = this.props
    const { userEmail, claimsFilter } = this.state
    swal({
      title: 'Report will be sent to your email ',
      input: 'email',
      inputValue: userEmail,
      showCancelButton: true,
      confirmButtonText: 'Send',
      showLoaderOnConfirm: true,
      preConfirm: mail => {
        this.props.sendClaimsReport({
          email: mail,
          owner_id: userDetail.id,
          download_type: 'open_claim_list',
          ...claimsFilter
        })
      },
      allowOutsideClick: () => false
    }).then(result => {
      if (result.dismiss !== 'cancel') {
        swal({
          type: 'success',
          title: '',
          text: 'success'
        })
      }
    })
  };

  getColumnProps (key) {
    const {
      filtersData,
      getClaimsFiltersLoading,
      getClaimsFiltersError,
      permissions
    } = this.props
    const { searchTextQuery, isChange, filteredInfo } = this.state
    const filteredColor = filteredInfo[key] ? '#1890ff' : undefined
    const querySearch = QueryString.parse(this.props.location.search)
    if (
      !getClaimsFiltersLoading &&
      !getClaimsFiltersError &&
      Array.isArray(filtersData)
    ) {
      if (!(permissions.indexOf('ops.claim_filter_product_name') > -1) && key === 'product_key') { return {} }
      if (!(permissions.indexOf('ops.claim_filter_package_name') > -1) && key === 'package_name') { return {} }

      const keyFilterProp = filtersData.find(x => x.name === key)
      if (!keyFilterProp) return {}
      const filterType = keyFilterProp.type
      if (filterType === 'choices') {
        let filterKeys = []
        const values = keyFilterProp.values || {}
        for (key in values) {
          filterKeys.push({
            text: values[key],
            value: key
          })
        }
        return {
          filters: filterKeys,
          filterMultiple: false,
          filteredValue: filteredInfo[key] || null,
          filterIcon: <Icon type='filter' style={{ color: filteredColor }} />
        }
      } else if (filterType === 'text') {
        let columnConfig = {
          filterIcon: (
            <Icon
              type='search'
              style={{
                color:
                  searchTextQuery[key] || querySearch[key]
                    ? '#1890ff'
                    : undefined
              }}
            />
          ),
          filterDropdown: (
            <FilterInput
              idIdentifier={key}
              searchText={
                isChange
                  ? searchTextQuery[key]
                  : querySearch[key] !== undefined
                    ? querySearch[key]
                    : searchTextQuery[key]
              }
              onInputChange={e => this.onInputChange(e, key)}
              onSearch={e => this.onSearch(e, key, filterType)}
            />
          ),
          filterDropdownVisible: this.state[key],
          onFilterDropdownVisibleChange: visible =>
            this.setState({ [key]: visible })
        }

        if (key === 'claim_number') {
          columnConfig = {
            ...columnConfig,
            render: (val, { claim_id: claimId }) => {
              return (
                <PermissionChecker
                  permissionSetter='ops.view_claim_details'
                  permissionGetter={permissions}
                >
                  <span
                    className='anchor'
                    onClick={() => this.detailPage(claimId)}
                  >
                    {val}
                  </span>
                </PermissionChecker>
              )
            }
          }
        }

        return columnConfig
      } else if (filterType === 'date_range') {
        return {
          filterDropdown: (
            <FilterDateRange
              idIdentifier={key}
              onSearch={e => this.onSearch(e, key, filterType)}
              isClear={this.state.clearDate}
              startDate={
                isChange
                  ? (searchTextQuery[key] || [])[0]
                  : (querySearch[key] || [])[0] !== undefined
                    ? (querySearch[key] || [])[0]
                    : (searchTextQuery[key] || [])[0]
              }
              endDate={
                isChange
                  ? (searchTextQuery[key] || [])[1]
                  : (querySearch[key] || [])[1] !== undefined
                    ? (querySearch[key] || [])[1]
                    : (searchTextQuery[key] || [])[1]
              }
            />
          ),
          filterIcon: (
            <Icon
              style={{
                color:
                  (searchTextQuery[key] !== undefined &&
                    searchTextQuery[key] !== undefined) ||
                    (querySearch[key] !== undefined &&
                      querySearch[key] !== undefined)
                    ? '#108ee9'
                    : '#aaa'
              }}
              type='filter'
              theme='outlined'
            />
          ),
          filterDropdownVisible: this.state[key],
          onFilterDropdownVisibleChange: visible =>
            this.setState({ [key]: visible })
        }
      } else {
        return {}
      }
    } else {
      return {}
    }
  }

  render () {
    const {
      claimsFilter } = this.state
    const {
      getOpenClaimsLoading,
      getOpenClaimsError,
      openClaimsData,
      permissions,
      profileData
    } = this.props
    const metaData = openClaimsData.meta_data
    const claimsList = (openClaimsData || {}).data || []
    const totalData = metaData ? metaData.total_records : 0
    const page = metaData ? metaData.page : 1

    const columns = [
      {
        key: 'policy_number',
        title: (
          <div
            style={{
              display: 'flex',
              paddingTop: '2px',
              marginLeft: '20px'
            }}
          >
            <span>Policy number</span>
          </div>
        ),
        dataIndex: 'policy_number',
        ...this.getColumnProps('policy_number')
      },
      {
        key: 'claim_no',
        title: (
          <div
            style={{
              display: 'flex',
              paddingTop: '2px',
              marginLeft: '20px'
            }}
          >
            <span>Claim id</span>
          </div>
        ),
        dataIndex: 'claim_no',
        ...this.getColumnProps('claim_number')
      },
      {
        key: 'partnerproduct_id',
        title: (
          <div
            style={{
              display: 'flex',
              paddingTop: '2px'
            }}
          >
            <span>Product Name</span>
          </div>
        ),
        dataIndex: 'display_name',
        ...ColumnSearchProps(this, 'partnerproduct_id', 'product')

      },
      {
        key: 'benefit',
        title: (
          <div
            style={{
              display: 'flex',
              paddingTop: '2px'
            }}
          >
            <span>Benefit</span>
          </div>
        ),
        dataIndex: 'benefit'
      },
      {
        title: 'Doc Completed/Received Date',
        dataIndex: 'doc_complete_received_date',
        key: 'doc_complete_received_date',
        render: val => (
          profileData
            ? moment.utc(val, 'DD/MM/YYYY HH:mm:ss').tz(profileData.user_timezone).format('DD MMMM YYYY HH:mm:ss')
            : ''
        )
      },
      {
        title: 'Status',
        dataIndex: 'status',
        key: 'status',
        ...this.getColumnProps('status')
      }
    ]
    return (
      <LayoutContentWrapper
        className='referral-table'
        style={{ color: '#788195' }}
      >
        <Row style={{ width: '100%' }}>
          <Col>
            <FailedFetchAlert
              status={'error'}
              isNeedDisplay={this.state.failedMessage !== ''}
              onClose={this.resetReduxState}
              message={this.state.failedMessage}
            />
          </Col>
        </Row>
        <LayoutContent>
          <Row style={{ marginBottom: '10px' }}>
            <div>
              <h3 style={{ float: 'left', color: '#788195' }}>Claim Lists</h3>
              <div>
                <p
                  style={{
                    float: 'left',
                    color: '#4482FF',
                    marginLeft: '10px',
                    marginTop: '3px'
                  }}
                >
                  {totalData}
                </p>
              </div>
            </div>
            {Object.keys(claimsFilter).length > 0 && (
              <Tag
                style={{ alignSelf: 'center', marginLeft: '5px' }}
                color='purple'
              >
                Filter is applied
              </Tag>
            )}
            <div style={{ float: 'right', display: 'flex' }}>
              <Button onClick={this.resetFilter}>
                <Icon type='filter' theme='outlined' /> &nbsp;Clear filter
              </Button>
              <div
                span={
                  permissions.length &&
                    permissions.indexOf('ops.download_claims_list') > -1
                    ? 8
                    : 3
                }
              >
                <div style={{ display: 'flex', float: 'right' }}>
                  <PermissionChecker
                    permissionSetter='ops.download_claims_list'
                    permissionGetter={permissions}
                  >
                    <Button
                      onClick={this.downloadExcel}
                      style={{ marginLeft: '10px' }}
                    >
                      <Icon type='cloud' theme='outlined' /> &nbsp;Download
                    </Button>
                  </PermissionChecker>
                </div>
              </div>
            </div>
          </Row>
          <TableWrapper
            bordered
            columns={columns}
            pagination={{
              pageSize: 50,
              total: totalData,
              current: page
            }}
            rowKey={record => record.claim_id}
            dataSource={
              !getOpenClaimsError && !getOpenClaimsLoading ? claimsList : []
            }
            loading={getOpenClaimsLoading}
            className='isoSearchableTable'
            onChange={this.handleTableChange}
          />
        </LayoutContent>
      </LayoutContentWrapper>
    )
  }
}

OpenClaims.propTypes = {
  openClaimsData: PropTypes.object.isRequired
}

OpenClaims.defaultProps = {
  openClaimsData: {}
}

export default connect(
  state => ({
    openClaimsData: state.Claims.openClaimsData,
    getOpenClaimsStatus: state.Claims.getOpenClaimsStatus,
    getOpenClaimsLoading: state.Loading.GET_OPEN_CLAIMS,
    getOpenClaimsError: state.Error.GET_OPEN_CLAIMS,
    getClaimsFiltersLoading: state.Loading.GET_CLAIM_FILTERS,
    getClaimsFiltersError: state.Error.GET_CLAIM_FILTERS,
    filtersData: state.Claims.filtersData,
    profileData: state.Auth.profile,
    groupLists: state.Team,
    dataValidateGocar: state.Claims.dataValidateGocar,
    userDetail: state.Auth.profile
  }),
  {
    getOpenClaims,
    getClaimFilters,
    resetReduxStateClaim,
    sendClaimsReport,
    resetLoadingRedux,
    resetErrorRedux,
    getListGroups,
    resetValidateStatus,
    getProducts
  }
)(OpenClaims)
